export PYTHONDONTWRITEBYTECODE=1
X() { /usr/bin/python3 ext2check.py "$@"; }
O() { /usr/bin/python3 outcome.py "$@"; }
G() { /usr/bin/python3 ext2groups.py "$@"; }
/usr/bin/python3 -c 'import sys; open(sys.argv[1], "wb").write(bytes([165]) * 67108864)' big1024.img
{ mkfs big1024.img
} >big1024.img.out 2>big1024.img.err; O big1024.img "$?" big1024.img.out big1024.img.err
X layout big1024.img
G groups big1024.img
/usr/bin/rm -f big1024.img
shopt -s nullglob; left=(*.img); [[ ${#left[@]} == 0 ]] && echo "images removed" || echo "left: ${left[*]}"

